function prepareCvInput({ pdfUrl, jobDescription }) {
  if (
    typeof pdfUrl !== "string" ||
    !/^https?:\/\/[^/?#\s@]+(?:[/?#]|$)/i.test(pdfUrl.trim()) ||
    /\s/.test(pdfUrl.trim())
  )
    throw new Error("Provide a public HTTP or HTTPS PDF URL without embedded credentials.");
  if (typeof jobDescription !== "string" || !jobDescription.trim())
    throw new Error("Provide the complete job description.");
  return { pdfUrl: pdfUrl.trim(), jobDescription };
}

return $input
  .all()
  .map((item, index) => ({ json: prepareCvInput(item.json), pairedItem: { item: index } }));

function prepareCvText({ pdfUrl, jobDescription, body }) {
  if (typeof body !== "string" || !body.trim())
    throw new Error(
      "The PDF extractor did not return inline resume text. No assessment was generated.",
    );
  return {
    reportInput: JSON.stringify({ job_description: jobDescription, resume_text: body }),
    pdfUrl,
  };
}

const items = $input.all(),
  roles = $("Validate Resume Input").all();
if (items.length !== roles.length) throw new Error("PDF text count differs from resume inputs.");
return items.map((item, index) => ({
  json: prepareCvText({ ...roles[index].json, body: item.json.text }),
  pairedItem: { item: index },
}));

function validateCvReport({ result, pdfUrl }) {
  const required = ["percentage", "summary", "reasons-suit", "reasons-notsuit"];
  if (
    !result ||
    typeof result !== "object" ||
    Array.isArray(result) ||
    Object.keys(result).some((k) => !required.includes(k))
  )
    throw new Error("The assessment must match the candidate evaluation structure.");
  if (
    !Number.isInteger(result.percentage) ||
    result.percentage < 0 ||
    result.percentage > 100 ||
    result.percentage % 10 !== 0
  )
    throw new Error("The matching percentage must be0–100 in10-point steps.");
  if (typeof result.summary !== "string" || !result.summary.trim())
    throw new Error("The assessment summary is empty.");
  for (const key of ["reasons-suit", "reasons-notsuit"]) {
    if (!Array.isArray(result[key])) throw new Error("Assessment reasons must be arrays.");
    for (const reason of result[key])
      if (
        !reason ||
        typeof reason !== "object" ||
        Array.isArray(reason) ||
        Object.keys(reason).some((k) => !["name", "text"].includes(k)) ||
        typeof reason.name !== "string" ||
        !reason.name.trim() ||
        typeof reason.text !== "string" ||
        !reason.text.trim()
      )
        throw new Error("Each assessment reason needs a name and text.");
  }
  return { evaluation: result, sourceUrl: pdfUrl };
}

const items = $input.all(),
  sources = $("Prepare Complete CV and Job").all();
if (items.length !== sources.length) throw new Error("Assessment count differs from resume count.");
return items.map((item, index) => {
  const choice = item.json.choices?.[0];
  if (choice?.message?.refusal || choice?.finish_reason !== "stop")
    throw new Error("The model did not complete a candidate report.");
  let result;
  try {
    result = JSON.parse(choice.message.content);
  } catch {
    throw new Error("The model report is not JSON.");
  }
  return {
    json: validateCvReport({ result, pdfUrl: sources[index].json.pdfUrl }),
    pairedItem: { item: index },
  };
});
